def build_agent(sandbox):
    DENSITY = 170.0
    RESTITUTION = 0.0

    # Upper sieve: blocks medium, allows large
    upper_positions = [5.25, 5.65, 6.05, 6.45]  # 0.4 m spacing (0.32 m gap)
    for x in upper_positions:
        beam = sandbox.add_static_beam(x, 2.52, 0.08, 0.08, density=DENSITY)
        sandbox.set_material_properties(beam, restitution=RESTITUTION)

    # Middle sieve: blocks small, allows medium
    middle_positions = [5.5, 5.74]  # 0.24 m spacing (0.16 m gap)
    for x in middle_positions:
        beam = sandbox.add_static_beam(x, 2.22, 0.08, 0.08, density=DENSITY)
        sandbox.set_material_properties(beam, restitution=RESTITUTION)

    return upper_positions[0]

def agent_action(sandbox, agent_body, step_count):
    NUDGE_PERIOD = 32
    if step_count % NUDGE_PERIOD != 0:
        return

    # Apply downward force to small particles above the small zone
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -30.0))

    # Apply downward force to medium particles above the medium zone
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -25.5))

    # Apply upward force to large particles below the large zone
    for p in sandbox.get_particles_large():
        if p.active and p.position.y < 2.52:
            sandbox.apply_force(p, (0, 25.5))
